-- STRICTLY READ ONLY: run before 202608280001_oil_supplier_accounting.sql
with checks(check_name,status,details,blocking) as (
 values
 ('OIL_PHASE_1_TABLES',case when to_regclass('public.oil_shops') is not null and to_regclass('public.oil_purchases') is not null and to_regclass('public.oil_vehicle_entries') is not null then 'PASS' else 'FAIL' end,'Oil Phase 1 source tables must exist',true),
 ('CASHBOOK_TABLE',case when to_regclass('public.cashbook_entries') is not null then 'PASS' else 'FAIL' end,'Cashbook table is required',true),
 ('SOURCE_ID_TYPES',case when (select data_type from information_schema.columns where table_schema='public' and table_name='oil_purchases' and column_name='id')='uuid' and (select data_type from information_schema.columns where table_schema='public' and table_name='oil_vehicle_entries' and column_name='id')='uuid' and (select data_type from information_schema.columns where table_schema='public' and table_name='oil_shops' and column_name='id')='uuid' then 'PASS' else 'FAIL' end,'Oil source and supplier IDs must be uuid',true),
 ('TENANT_HELPERS',case when to_regprocedure('public.current_user_adda_id()') is not null and to_regprocedure('public.current_user_role()') is not null and to_regprocedure('public.is_super_admin()') is not null then 'PASS' else 'FAIL' end,'Required tenant helpers',true),
 ('PHASE_2_DEPLOYMENT_STATE',case when to_regclass('public.oil_supplier_bills') is null and to_regclass('public.oil_supplier_payments') is null and to_regclass('public.oil_supplier_payment_allocations') is null then 'PASS' else 'FAIL' end,'All Phase 2 tables must be absent before this first deployment',true),
 ('RPC_CONFLICTS',case when not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('rebuild_oil_supplier_accounting','save_oil_supplier_payment','delete_oil_supplier_payment')) then 'PASS' else 'FAIL' end,'No unexpected supplier accounting RPC overloads',true),
 ('HISTORICAL_PAID_PURCHASES',case when not exists(select 1 from public.oil_purchases where coalesce(paid_amount,0)<>0) then 'PASS' else 'FAIL' end,'Non-zero legacy purchase paid amounts cannot be reconstructed safely and must be reconciled first',true),
 ('INVALID_EXTERNAL_PURCHASE_SUPPLIERS',case when not exists(select 1 from public.oil_purchases p left join public.oil_shops s on s.id=p.oil_shop_id where s.id is null or s.adda_id<>p.adda_id or s.shop_type<>'external_supplier') then 'PASS' else 'FAIL' end,'Every purchase must resolve to a same-Adda external supplier',true),
 ('INVALID_EXTERNAL_VEHICLE_SUPPLIERS',case when not exists(select 1 from public.oil_vehicle_entries e left join public.oil_shops s on s.id=e.oil_shop_id where e.source_type='external_shop' and (s.id is null or s.adda_id<>e.adda_id or s.shop_type<>'external_supplier')) then 'PASS' else 'FAIL' end,'Every external-shop vehicle bill must resolve to a same-Adda external supplier',true),
 ('NON_POSITIVE_SOURCE_BILLS',case when not exists(select 1 from public.oil_purchases where total_amount<=0) and not exists(select 1 from public.oil_vehicle_entries where source_type='external_shop' and total_amount<=0) then 'PASS' else 'FAIL' end,'Supplier bill sources must be positive',true),
 ('DUPLICATE_CASHBOOK_REFERENCES',case when not exists(select 1 from public.cashbook_entries where reference_type='oil_supplier_payment' group by reference_id having count(*)>1) then 'PASS' else 'FAIL' end,'No duplicate automatic Oil supplier payment references',true),
 ('EXISTING_OIL_SUPPLIER_CASHBOOK_ROWS',case when not exists(select 1 from public.cashbook_entries where reference_type='oil_supplier_payment') then 'PASS' else 'FAIL' end,'No unexplained pre-deployment Oil supplier Cashbook rows',true),
 ('SOURCE_RLS',case when coalesce((select relrowsecurity from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname='oil_purchases'),false) and coalesce((select relrowsecurity from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname='oil_vehicle_entries'),false) then 'PASS' else 'FAIL' end,'Oil source RLS must remain enabled',true),
 ('SOURCE_COUNTS','INFO',(select format('%s purchases; %s external vehicle bills',(select count(*) from public.oil_purchases),(select count(*) from public.oil_vehicle_entries where source_type='external_shop'))),false)
), combined as (
 select 'OVERALL_OIL_SUPPLIER_ACCOUNTING_PREFLIGHT'::text check_name,case when count(*) filter(where blocking and status='FAIL')=0 then 'PASS' else 'FAIL' end status,format('%s blocking check(s) failed; %s passed; %s informational',count(*) filter(where blocking and status='FAIL'),count(*) filter(where status='PASS'),count(*) filter(where status='INFO')) details from checks
 union all select check_name,status,details from checks
)
select check_name,status,details from combined order by case when check_name='OVERALL_OIL_SUPPLIER_ACCOUNTING_PREFLIGHT' then 0 else 1 end,check_name;
